<script setup lang="ts">
import {computed} from 'vue';
const props=defineProps<{task:any;canChangeStatus:boolean;canQuickAssign:boolean}>();const emit=defineEmits(['open','assign','drag']);
const seconds=computed(()=>(props.task.timer_logs||[]).reduce((sum:number,l:any)=>sum+(l.start_time?Math.max(0,(new Date(l.end_time||Date.now()).getTime()-new Date(l.start_time).getTime())/1000):0),0));const logged=computed(()=>{const h=Math.floor(seconds.value/3600),m=Math.floor(seconds.value%3600/60);return (h?h+'h ':'')+(m?m+'m':h?'':'< 1m');});const percent=computed(()=>props.task.original_estimate_minutes?Math.round(seconds.value/(props.task.original_estimate_minutes*60)*100):0);const color=computed(()=>percent.value>100?'danger':percent.value>=80?'warning':'success');const priority=computed(()=>['Low','Normal','High','Urgent'][props.task.priority??1]);
</script>
<template><article class="work-card" :draggable="canChangeStatus" @dragstart="emit('drag',task.id)" @dragend="emit('drag',null)" @click="emit('open',task.id)"><div class="d-flex justify-content-between gap-2"><span class="work-key">{{(task.project?.name||'TSK').slice(0,3).toUpperCase()}}-{{task.id}}</span><span class="badge bg-label-primary project-chip" :title="task.project?.name">{{task.project?.name}}</span></div><div class="work-title">{{task.title}}</div><div class="d-flex align-items-center justify-content-between gap-2 mb-2"><span class="badge" :class="task.sprint?'bg-label-info':'bg-label-secondary'"><i class="fa fa-bolt me-1"></i>{{task.sprint?.name||'Backlog'}}</span><span v-if="task.sprint" class="work-meta text-capitalize">{{task.sprint.status}}</span></div><div v-if="task.original_estimate_minutes" class="mb-2"><span class="badge" :class="'bg-label-'+color"><i class="fa fa-hourglass-half me-1"></i>{{percent}}% of estimate</span></div><div class="d-flex justify-content-between align-items-center gap-2"><div class="d-flex align-items-center gap-2 work-meta flex-wrap"><span :class="['text-secondary','text-info','text-warning','text-danger'][task.priority??1]" :title="priority+' priority'"><i class="fa" :class="['fa-arrow-down','fa-equals','fa-arrow-up','fa-angles-up'][task.priority??1]"></i></span><span v-if="seconds" title="Total time logged"><i class="fa fa-clock"></i> {{logged}}</span><span v-if="task.subtasks_count" title="Subtasks"><i class="fa fa-list-check"></i> {{task.subtasks_count}}</span><span v-if="task.comments_count" title="Comments"><i class="fa fa-comment"></i> {{task.comments_count}}</span><span v-if="task.attachments_count" title="Attachments"><i class="fa fa-paperclip"></i> {{task.attachments_count}}</span><span v-if="task.due_date" :class="new Date(task.due_date).getTime()<Date.now()&&task.status!=='completed'?'text-danger fw-semibold':''"><i class="fa fa-calendar"></i> {{new Date(task.due_date).toLocaleDateString('en-US',{month:'short',day:'2-digit'})}}</span></div><div class="d-flex align-items-center"><button v-if="canQuickAssign" type="button" class="btn btn-sm p-0 border-0 work-assignee-toggle" :aria-label="task.users?.length?'Manage assignees':'Assign employee'" @click.stop="emit('assign',task)"><span v-if="task.users?.length" class="d-flex align-items-center"><img v-for="u in task.users.slice(0,3)" :key="u.id" class="work-avatar" :src="u.profile_img||'/pms-assets/assets/img/user-picture.png'" :title="u.name" :alt="u.name"><small v-if="task.users.length>3" class="ms-1">+{{task.users.length-3}}</small></span><span v-else class="work-avatar m-0 d-inline-flex align-items-center justify-content-center"><i class="fa fa-user-plus text-primary"></i></span></button><template v-else><img v-for="u in task.users?.slice(0,3)" :key="u.id" class="work-avatar" :src="u.profile_img||'/pms-assets/assets/img/user-picture.png'" :title="u.name" :alt="u.name"><span v-if="!task.users?.length" class="work-meta"><i class="fa" :class="task.subtasks_count?'fa-code-branch':'fa-user-slash'"></i> {{task.subtasks_count?'Subtask':'Unassigned'}}</span></template></div></div></article></template>
